// Longest punctuation first, so the scanner tries multi-character operators
// before falling back to their single-character prefixes.
const PUNCTUATION = [
  '==', '!=', '<=', '>=', '&&', '||', '->', '=>',
  '+', '-', '*', '/', '%', '=', '<', '>', '!',
  '(', ')', '{', '}', '[', ']', ',', ';', '.',
]

export class LexError extends Error {
  constructor(line, column, reason) {
    super(reason)
    this.line = line
    this.column = column
    this.reason = reason
  }
}

function isLetter(c) {
  return c !== undefined && /[A-Za-z]/.test(c)
}

function isDecimalDigit(c) {
  return c !== undefined && /[0-9]/.test(c)
}

function isHexDigit(c) {
  return c !== undefined && /[0-9A-Fa-f]/.test(c)
}

function isBinDigit(c) {
  return c === '0' || c === '1'
}

function isOctDigit(c) {
  return c !== undefined && /[0-7]/.test(c)
}

function isIdentStart(c) {
  return c === '_' || isLetter(c)
}

function isIdentPart(c) {
  return c === '_' || isLetter(c) || isDecimalDigit(c)
}

class Scanner {
  constructor(source) {
    this.chars = Array.from(source)
    this.pos = 0
    this.line = 1
    this.column = 1
  }

  atEnd() {
    return this.pos >= this.chars.length
  }

  peek(offset = 0) {
    return this.chars[this.pos + offset]
  }

  here() {
    return { line: this.line, column: this.column }
  }

  fail(pos, reason) {
    throw new LexError(pos.line, pos.column, reason)
  }

  // Consumes exactly one code point, updating the line/column of the
  // position that follows it.
  advance() {
    const c = this.chars[this.pos]
    this.pos++
    if (c === '\n') {
      this.line++
      this.column = 1
    } else if (c === '\t') {
      this.column += 4 - ((this.column - 1) % 4)
    } else {
      this.column++
    }
    return c
  }

  scanTokens() {
    const tokens = []
    while (true) {
      this.skipTrivia()
      if (this.atEnd()) break
      tokens.push(this.scanToken())
    }
    return tokens
  }

  // Skips whitespace and comments; leaves the scanner positioned at the
  // start of the next token, or at the end of the input.
  skipTrivia() {
    while (!this.atEnd()) {
      const c = this.peek()
      if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
        this.advance()
        continue
      }
      if (c === '/' && this.peek(1) === '/') {
        this.advance()
        this.advance()
        while (!this.atEnd() && this.peek() !== '\n') this.advance()
        continue
      }
      if (c === '/' && this.peek(1) === '*') {
        this.skipBlockComment()
        continue
      }
      break
    }
  }

  skipBlockComment() {
    const start = this.here()
    this.advance()
    this.advance()
    let depth = 1
    while (depth > 0) {
      if (this.atEnd()) this.fail(start, 'unterminated block comment')
      if (this.peek() === '/' && this.peek(1) === '*') {
        this.advance()
        this.advance()
        depth++
      } else if (this.peek() === '*' && this.peek(1) === '/') {
        this.advance()
        this.advance()
        depth--
      } else {
        this.advance()
      }
    }
  }

  scanToken() {
    const start = this.here()
    const c = this.peek()
    if (c === '"') return this.scanString(start)
    if (c === 'r' && this.peek(1) === '"') return this.scanRawString(start)
    if (isIdentStart(c)) return this.scanIdent(start)
    if (isDecimalDigit(c)) return this.scanNumber(start)
    return this.scanPunct(start)
  }

  scanIdent(start) {
    let text = ''
    while (isIdentPart(this.peek())) text += this.advance()
    const kind = KEYWORDS.has(text) ? 'keyword' : 'ident'
    return { ...start, kind, body: text }
  }

  scanPunct(start) {
    for (const p of PUNCTUATION) {
      let matches = true
      for (let i = 0; i < p.length; i++) {
        if (this.peek(i) !== p[i]) {
          matches = false
          break
        }
      }
      if (matches) {
        for (let i = 0; i < p.length; i++) this.advance()
        return { ...start, kind: 'punct', body: p }
      }
    }
    const c = this.peek()
    this.fail(start, `unexpected character ${c}`)
  }

  // Consumes a run of digits (per `isDigit`) allowing a single underscore
  // between two digits of the run, and returns the text consumed.
  consumeDigitRun(isDigit) {
    let text = ''
    let lastWasDigit = false
    while (!this.atEnd()) {
      const c = this.peek()
      if (isDigit(c)) {
        text += this.advance()
        lastWasDigit = true
      } else if (c === '_' && lastWasDigit && isDigit(this.peek(1))) {
        text += this.advance()
        lastWasDigit = false
      } else {
        break
      }
    }
    return text
  }

  consumeTrailingJunk() {
    let text = ''
    while (isIdentPart(this.peek())) text += this.advance()
    return text
  }

  scanNumber(start) {
    let text = ''
    const first = this.peek()
    const second = this.peek(1)
    const prefixKind =
      first === '0' && (second === 'x' || second === 'X')
        ? 'x'
        : first === '0' && (second === 'b' || second === 'B')
          ? 'b'
          : first === '0' && (second === 'o' || second === 'O')
            ? 'o'
            : null

    if (prefixKind !== null) {
      text += this.advance()
      text += this.advance()
      const isDigit = prefixKind === 'x' ? isHexDigit : prefixKind === 'b' ? isBinDigit : isOctDigit
      const digits = this.consumeDigitRun(isDigit)
      text += digits
      if (digits === '') {
        text += this.consumeTrailingJunk()
        this.fail(start, `invalid number ${text}`)
      }
